CREATE TABLE public.finance_schedule_settings (tenant_id uuid PRIMARY KEY REFERENCES public.tenants(id),capitalisation_limit numeric NOT NULL DEFAULT 5000 CHECK(capitalisation_limit>0),stock_basis text NOT NULL DEFAULT 'purchases' CHECK(stock_basis IN('purchases','counts')),voucher_enabled boolean NOT NULL DEFAULT false,deposit_enabled boolean NOT NULL DEFAULT false,package_enabled boolean NOT NULL DEFAULT false,voucher_expiry_months integer NOT NULL DEFAULT 12 CHECK(voucher_expiry_months BETWEEN 1 AND 120),jurisdiction text NOT NULL DEFAULT 'HK' CHECK(jurisdiction='HK'),year_end_month integer NOT NULL DEFAULT 3 CHECK(year_end_month BETWEEN 1 AND 12),year_end_day integer NOT NULL DEFAULT 31 CHECK(year_end_day BETWEEN 1 AND 31),business_type text NOT NULL DEFAULT 'company' CHECK(business_type IN('company','unincorporated')),filed_by text NOT NULL DEFAULT '',tax_enabled boolean NOT NULL DEFAULT false,assessment_dates jsonb NOT NULL DEFAULT '[]',updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
GRANT SELECT ON public.finance_schedule_settings TO authenticated;GRANT ALL ON public.finance_schedule_settings TO service_role;ALTER TABLE public.finance_schedule_settings ENABLE ROW LEVEL SECURITY;CREATE POLICY schedule_settings_read ON public.finance_schedule_settings FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id));
CREATE TABLE public.finance_entry_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),entry_date date NOT NULL,kind text NOT NULL,label text NOT NULL,reason text NOT NULL DEFAULT '',source_document text,linked_entry_id uuid REFERENCES public.journal_entries(id),source_key text NOT NULL,source_data jsonb NOT NULL DEFAULT '{}',lines jsonb NOT NULL,status text NOT NULL DEFAULT 'waiting' CHECK(status IN('waiting','approved','cancelled')),journal_entry_id uuid REFERENCES public.journal_entries(id),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),approved_by uuid,approved_at timestamptz,UNIQUE(tenant_id,source_key));
GRANT SELECT ON public.finance_entry_drafts TO authenticated;GRANT ALL ON public.finance_entry_drafts TO service_role;ALTER TABLE public.finance_entry_drafts ENABLE ROW LEVEL SECURITY;CREATE POLICY schedule_drafts_read ON public.finance_entry_drafts FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id));
CREATE TABLE public.finance_deferred_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),kind text NOT NULL CHECK(kind IN('voucher','deposit','package')),reference text NOT NULL,guest_event text NOT NULL DEFAULT '',venue text,issued_date date NOT NULL,amount numeric NOT NULL CHECK(amount>0),used_amount numeric NOT NULL DEFAULT 0,expires_on date,release_months integer NOT NULL DEFAULT 1 CHECK(release_months BETWEEN 1 AND 120),source_document text,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','closed')),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL DEFAULT auth.uid(),UNIQUE(tenant_id,reference),CHECK(used_amount BETWEEN 0 AND amount));
GRANT SELECT ON public.finance_deferred_items TO authenticated;GRANT ALL ON public.finance_deferred_items TO service_role;ALTER TABLE public.finance_deferred_items ENABLE ROW LEVEL SECURITY;CREATE POLICY deferred_items_read ON public.finance_deferred_items FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id));
ALTER TABLE public.petty_cash_floats ADD COLUMN IF NOT EXISTS kept_by text NOT NULL DEFAULT '',ADD COLUMN IF NOT EXISTS topup_account_id uuid REFERENCES public.bank_accounts(id);
CREATE FUNCTION public.finance_schedule_manager(t uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.user_has_tenant(auth.uid(),t) AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=t AND user_id=auth.uid() AND role='owner')); $$;
REVOKE ALL ON FUNCTION public.finance_schedule_manager(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_schedule_manager(uuid) TO authenticated;
CREATE FUNCTION public.finance_schedule_account(t uuid,c text,n text,k text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a uuid;BEGIN SELECT id INTO a FROM chart_of_accounts WHERE tenant_id=t AND code=c;IF a IS NULL THEN INSERT INTO chart_of_accounts(tenant_id,code,name,account_type,normal_side) VALUES(t,c,n,k,CASE WHEN k IN('liability','equity','revenue','other_income') THEN 'credit' ELSE 'debit' END) RETURNING id INTO a;END IF;RETURN a;END $$;REVOKE ALL ON FUNCTION public.finance_schedule_account(uuid,text,text,text) FROM PUBLIC;
CREATE FUNCTION public.finance_schedule_save_settings(t uuid,p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;
INSERT INTO finance_schedule_settings(tenant_id,capitalisation_limit,stock_basis,voucher_enabled,deposit_enabled,package_enabled,voucher_expiry_months,jurisdiction,year_end_month,year_end_day,business_type,filed_by,tax_enabled,assessment_dates,updated_by) VALUES(t,coalesce((p->>'capitalisation_limit')::numeric,5000),coalesce(p->>'stock_basis','purchases'),coalesce((p->>'voucher_enabled')::boolean,false),coalesce((p->>'deposit_enabled')::boolean,false),coalesce((p->>'package_enabled')::boolean,false),coalesce((p->>'voucher_expiry_months')::int,12),coalesce(p->>'jurisdiction','HK'),coalesce((p->>'year_end_month')::int,3),coalesce((p->>'year_end_day')::int,31),coalesce(p->>'business_type','company'),coalesce(p->>'filed_by',''),coalesce((p->>'tax_enabled')::boolean,false),coalesce(p->'assessment_dates','[]'),auth.uid()) ON CONFLICT(tenant_id) DO UPDATE SET capitalisation_limit=excluded.capitalisation_limit,stock_basis=excluded.stock_basis,voucher_enabled=excluded.voucher_enabled,deposit_enabled=excluded.deposit_enabled,package_enabled=excluded.package_enabled,voucher_expiry_months=excluded.voucher_expiry_months,jurisdiction=excluded.jurisdiction,year_end_month=excluded.year_end_month,year_end_day=excluded.year_end_day,business_type=excluded.business_type,filed_by=excluded.filed_by,tax_enabled=excluded.tax_enabled,assessment_dates=excluded.assessment_dates,updated_by=auth.uid(),updated_at=now();
IF (p->>'voucher_enabled')::boolean OR (p->>'deposit_enabled')::boolean OR (p->>'package_enabled')::boolean THEN PERFORM finance_schedule_account(t,'2300','Deferred revenue','liability');END IF;IF p->>'stock_basis'='counts' THEN PERFORM finance_schedule_account(t,'1400','Inventory','asset');END IF;IF (p->>'tax_enabled')::boolean THEN PERFORM finance_schedule_account(t,'6950','Profits tax expense','other_expense');PERFORM finance_schedule_account(t,'2350','Tax payable','liability');END IF;
INSERT INTO audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(t,auth.uid(),'finance_schedule_settings_saved','finance_schedule_settings',t::text,p);END $$;REVOKE ALL ON FUNCTION public.finance_schedule_save_settings(uuid,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_schedule_save_settings(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.finance_schedule_enqueue(t uuid,d date,k text,title text,why text,key text,ls jsonb,meta jsonb DEFAULT '{}',doc text DEFAULT NULL,linked uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ident uuid;l jsonb;dr numeric:=0;cr numeric:=0;BEGIN
IF NOT public.finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM finance_assert_open(t,d);IF jsonb_typeof(ls)<>'array' OR jsonb_array_length(ls)<2 OR jsonb_array_length(ls)>100 THEN RAISE EXCEPTION 'Two or more lines required';END IF;
FOR l IN SELECT * FROM jsonb_array_elements(ls) LOOP IF NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE id=(l->>'account_id')::uuid AND tenant_id=t AND is_active) THEN RAISE EXCEPTION 'Account unavailable';END IF;IF coalesce((l->>'debit')::numeric,0)<0 OR coalesce((l->>'credit')::numeric,0)<0 OR ((l->>'debit')::numeric>0 AND (l->>'credit')::numeric>0) THEN RAISE EXCEPTION 'Invalid line amount';END IF;IF l->>'venue' IS NOT NULL AND l->>'venue'<>'Central' AND NOT EXISTS(SELECT 1 FROM venues WHERE tenant_id=t AND name=l->>'venue') THEN RAISE EXCEPTION 'Venue unavailable';END IF;dr:=dr+coalesce((l->>'debit')::numeric,0);cr:=cr+coalesce((l->>'credit')::numeric,0);END LOOP;
IF dr<=0 OR dr<>cr OR dr<>round(dr,2) THEN RAISE EXCEPTION 'Debits and credits must balance to cents';END IF;IF linked IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries WHERE id=linked AND tenant_id=t) THEN RAISE EXCEPTION 'Linked entry unavailable';END IF;IF nullif(btrim(why),'') IS NULL AND doc IS NULL AND linked IS NULL THEN RAISE EXCEPTION 'Source document, linked entry or reason required';END IF;
INSERT INTO finance_entry_drafts(tenant_id,entry_date,kind,label,reason,source_key,lines,source_data,source_document,linked_entry_id) VALUES(t,d,k,title,why,key,ls,meta,doc,linked) ON CONFLICT(tenant_id,source_key) DO NOTHING RETURNING id INTO ident;RETURN coalesce(ident,(SELECT id FROM finance_entry_drafts WHERE tenant_id=t AND source_key=key));END $$;REVOKE ALL ON FUNCTION public.finance_schedule_enqueue(uuid,date,text,text,text,text,jsonb,jsonb,text,uuid) FROM PUBLIC;
CREATE FUNCTION public.finance_propose_journal(t uuid,d date,title text,why text,ls jsonb,doc text DEFAULT NULL,linked uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN finance_schedule_enqueue(t,d,'manual',title,why,'manual:'||gen_random_uuid()::text,ls,'{}',doc,linked);END $$;REVOKE ALL ON FUNCTION public.finance_propose_journal(uuid,date,text,text,jsonb,text,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_propose_journal(uuid,date,text,text,jsonb,text,uuid) TO authenticated;
CREATE FUNCTION public.finance_deferred_add(t uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ident uuid;a uuid;cash uuid;settings finance_schedule_settings;exp date;BEGIN IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;SELECT * INTO settings FROM finance_schedule_settings WHERE tenant_id=t;IF NOT (CASE p->>'kind' WHEN 'voucher' THEN settings.voucher_enabled WHEN 'deposit' THEN settings.deposit_enabled WHEN 'package' THEN settings.package_enabled ELSE false END) THEN RAISE EXCEPTION 'Enable this deferred revenue type in setup';END IF;SELECT id INTO a FROM chart_of_accounts WHERE tenant_id=t AND code='2300';SELECT id INTO cash FROM chart_of_accounts WHERE tenant_id=t AND id=(p->>'receipt_account_id')::uuid AND account_type='asset';IF cash IS NULL OR a IS NULL THEN RAISE EXCEPTION 'Choose the receipt account';END IF;
exp:=nullif(p->>'expires_on','')::date;IF exp IS NULL AND p->>'kind'='voucher' THEN exp:=((p->>'issued_date')::date+make_interval(months=>settings.voucher_expiry_months))::date;END IF;INSERT INTO finance_deferred_items(tenant_id,kind,reference,guest_event,venue,issued_date,amount,expires_on,release_months,source_document) VALUES(t,p->>'kind',p->>'reference',coalesce(p->>'guest_event',''),nullif(p->>'venue',''),(p->>'issued_date')::date,(p->>'amount')::numeric,exp,coalesce((p->>'release_months')::int,1),nullif(p->>'source_document','')) RETURNING id INTO ident;
PERFORM finance_schedule_enqueue(t,(p->>'issued_date')::date,'deferred_sold','Deferred revenue · '||(p->>'reference'),'Voucher/package sold or deposit taken','deferred-sold:'||ident,jsonb_build_array(jsonb_build_object('account_id',cash,'debit',(p->>'amount')::numeric,'credit',0,'venue',nullif(p->>'venue','')),jsonb_build_object('account_id',a,'credit',(p->>'amount')::numeric,'debit',0,'venue',nullif(p->>'venue',''))),jsonb_build_object('item',ident,'action','sold'));RETURN ident;END $$;REVOKE ALL ON FUNCTION public.finance_deferred_add(uuid,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_deferred_add(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.finance_deferred_use(t uuid,ident uuid,d date,amount numeric,action text,account uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i finance_deferred_items;a uuid;BEGIN IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;SELECT * INTO i FROM finance_deferred_items WHERE id=ident AND tenant_id=t FOR UPDATE;IF i.status<>'active' OR amount<=0 OR amount>i.amount-i.used_amount OR action NOT IN('used','refund') THEN RAISE EXCEPTION 'Deferred balance unavailable';END IF;IF NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE id=account AND tenant_id=t AND ((action='used' AND account_type='revenue') OR (action='refund' AND account_type='asset'))) THEN RAISE EXCEPTION 'Choose sales or refund account';END IF;SELECT id INTO a FROM chart_of_accounts WHERE tenant_id=t AND code='2300';RETURN finance_schedule_enqueue(t,d,'deferred_'||action,'Deferred revenue · '||i.reference,action,'deferred-'||action||':'||gen_random_uuid(),jsonb_build_array(jsonb_build_object('account_id',a,'debit',amount,'credit',0,'venue',i.venue),jsonb_build_object('account_id',account,'credit',amount,'debit',0,'venue',i.venue)),jsonb_build_object('item',ident,'action',action,'amount',amount,'expected_used',i.used_amount));END $$;REVOKE ALL ON FUNCTION public.finance_deferred_use(uuid,uuid,date,numeric,text,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_deferred_use(uuid,uuid,date,numeric,text,uuid) TO authenticated;